// Validar contraseña con lookahead múltiple
function validarPassword(pass) {
  const reglas = [
    { regex: /.{8,}/,         msg: 'mínimo 8 caracteres' },
    { regex: /[A-Z]/,         msg: 'al menos una mayúscula' },
    { regex: /[a-z]/,         msg: 'al menos una minúscula' },
    { regex: /\d/,            msg: 'al menos un número' },
    { regex: /[!@#$%^&*]/,   msg: 'al menos un carácter especial' },
  ];

  const errores = reglas
    .filter(r => !r.regex.test(pass))
    .map(r => r.msg);

  return {
    valida: errores.length === 0,
    errores,
  };
}

console.log(validarPassword('Pass1!'));           // inválida: corta
console.log(validarPassword('Contraseña1!'));     // válida
console.log(validarPassword('sinmayuscula1!'));   // falta mayúscula

// Extraer todos los imports de un archivo JS con matchAll
const codigoJS = `
import React from 'react';
import { useState, useEffect } from 'react';
import styles from './App.module.css';
import type { User } from './types';
`;

const importPattern = /^import\s+(?:type\s+)?(?:([\w]+)|\{([^}]+)\})\s+from\s+'([^']+)'/gm;

const imports = [];
for (const match of codigoJS.matchAll(importPattern)) {
  const [, defaultImport, namedImports, modulo] = match;
  imports.push({
    modulo,
    default: defaultImport?.trim() || null,
    named: namedImports?.split(',').map(s => s.trim()) || [],
  });
}

console.log(imports);
// [{ modulo: 'react', default: 'React', named: [] }, ...]

